 public sealed class GroupManager:ProjectDialog {public readonly ListBox groupAvailable=new ListBox(),groupOrdered=new ListBox();ListBox list=new ListBox();TextBox name=new TextBox();public GroupManager(Project p):base(p){Text="Display Groups";TableLayoutPanel t=Three("Groups","Available targets","Ordered group rows",list,groupAvailable,groupOrdered);groupAvailable.SelectionMode=SelectionMode.MultiExtended;Fmt(list,delegate(object x){return ((DisplayGroup)x).Name;});Fmt(groupAvailable,delegate(object x){return Target(working,(string)x);});Fmt(groupOrdered,delegate(object x){return Target(working,(string)x);});FlowLayoutPanel b=new FlowLayoutPanel(){Dock=DockStyle.Bottom,Height=36};b.Controls.Add(B("New",delegate{DisplayGroup g=new DisplayGroup();g.Id=Model.NewId();g.Name=NextGroupName();working.Groups.Add(g);Bind();list.SelectedItem=g;}));b.Controls.Add(B("Delete",delegate{if(Current()!=null){working.Groups.Remove(Current());Bind();}}));b.Controls.Add(new Label(){Text="Name"});b.Controls.Add(name);b.Controls.Add(B("Rename",delegate{if(Current()!=null){Current().Name=name.Text;Bind();}}));b.Controls.Add(B("Add →",delegate{if(Current()!=null)foreach(object x in groupAvailable.SelectedItems)if(!Current().Members.Contains((string)x))Current().Members.Add((string)x);Members();}));b.Controls.Add(B("Remove",delegate{if(Current()!=null&&groupOrdered.SelectedIndex>=0){Current().Members.RemoveAt(groupOrdered.SelectedIndex);Members();}}));b.Controls.Add(B("Up",delegate{Order(-1);}));b.Controls.Add(B("Down",delegate{Order(1);}));list.SelectedIndexChanged+=delegate{Members();};Controls.Add(t);Controls.Add(b);Controls.Add(Buttons());Bind();}protected override void Accept(){if(Current()!=null)Current().Name=name.Text.Trim();base.Accept();}DisplayGroup Current(){return list.SelectedItem as DisplayGroup;}void Bind(){object previous=list.SelectedItem;list.DataSource=null;list.Items.Clear();foreach(DisplayGroup g in working.Groups)list.Items.Add(g);if(previous!=null&&list.Items.Contains(previous))list.SelectedItem=previous;else if(list.Items.Count>0)list.SelectedIndex=0;groupAvailable.Items.Clear();foreach(string id in Model.TargetIds(working))groupAvailable.Items.Add(id);Members();}void Members(){groupOrdered.Items.Clear();if(Current()==null){name.Text="";return;}name.Text=Current().Name;foreach(string x in Current().Members)groupOrdered.Items.Add(x);}void Order(int d){int i=groupOrdered.SelectedIndex;if(Current()==null||i<0||i+d<0||i+d>=Current().Members.Count)return;string x=Current().Members[i];Current().Members.RemoveAt(i);Current().Members.Insert(i+d,x);Members();groupOrdered.SelectedIndex=i+d;}}
 public sealed class SegmentManager:ProjectDialog {ListBox list=new ListBox(),raw=new ListBox(),members=new ListBox();TextBox name=new TextBox();public SegmentManager(Project p):base(p){Text="Segments — raw membership only; HTP overlap";TableLayoutPanel t=Three("Segments","Raw channels","Members",list,raw,members);raw.SelectionMode=SelectionMode.MultiExtended;Fmt(list,delegate(object x){return ((Segment)x).Name;});Fmt(raw,delegate(object x){return Target(working,(string)x);});Fmt(members,delegate(object x){return Target(working,(string)x);});FlowLayoutPanel b=new FlowLayoutPanel(){Dock=DockStyle.Bottom,Height=36};b.Controls.Add(B("New",delegate{Segment x=new Segment();x.Id=Model.NewId();x.Name=NextSegmentName();working.Segments.Add(x);Bind();list.SelectedItem=x;}));b.Controls.Add(B("Delete",delegate{if(Current()!=null)try{Model.RemoveTarget(working,Current().Id);Bind();}catch(Exception x){MessageBox.Show(x.Message);}}));b.Controls.Add(name);b.Controls.Add(B("Rename",delegate{if(Current()!=null){Current().Name=name.Text;Bind();}}));b.Controls.Add(B("Add raw",delegate{if(Current()!=null)foreach(object x in raw.SelectedItems)if(!Current().Members.Contains((string)x))Current().Members.Add((string)x);Members();}));b.Controls.Add(B("Remove",delegate{if(Current()!=null&&members.SelectedIndex>=0){Current().Members.RemoveAt(members.SelectedIndex);Members();}}));list.SelectedIndexChanged+=delegate{Members();};Controls.Add(t);Controls.Add(b);Controls.Add(Buttons());Bind();}protected override void Accept(){if(Current()!=null)Current().Name=name.Text.Trim();base.Accept();}Segment Current(){return list.SelectedItem as Segment;}void Bind(){object previous=list.SelectedItem;list.DataSource=null;list.Items.Clear();foreach(Segment g in working.Segments)list.Items.Add(g);if(previous!=null&&list.Items.Contains(previous))list.SelectedItem=previous;else if(list.Items.Count>0)list.SelectedIndex=0;raw.Items.Clear();foreach(RawChannel x in working.Channels)raw.Items.Add(x.Id);Members();}void Members(){members.Items.Clear();if(Current()==null)return;name.Text=Current().Name;foreach(string x in Current().Members)members.Items.Add(x);}}
 static class U {public static Button B(string s,EventHandler h){Button b=new Button();b.Text=s;b.AutoSize=true;b.Click+=h;return b;}public static void Fmt(ListBox b,Func<object,string> f){b.FormattingEnabled=true;b.Format+=delegate(object s,ListControlConvertEventArgs e){e.Value=f(e.ListItem);};}public static TableLayoutPanel Three(string a,string b,string c,ListBox x,ListBox y,ListBox z){TableLayoutPanel t=new TableLayoutPanel(){Dock=DockStyle.Fill,ColumnCount=3,RowCount=2};for(int i=0;i<3;i++)t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,33));t.Controls.Add(new Label(){Text=a},0,0);t.Controls.Add(new Label(){Text=b},1,0);t.Controls.Add(new Label(){Text=c},2,0);x.Dock=y.Dock=z.Dock=DockStyle.Fill;t.Controls.Add(x,0,1);t.Controls.Add(y,1,1);t.Controls.Add(z,2,1);return t;}}
